fn mk_filled_vec(n: usize, val: f32) -> Vec<f32> {
    // Create a vector of length `n` where every element is `val`.
    vec![val; n]
}

fn lagval3d(
    x: Vec<f32>,
    y: Vec<f32>,
    z: Vec<f32>,
    c: Vec<Vec<Vec<f32>>>,
) -> Vec<f32> {
    // The output length is the same as the input arrays' length.
    // We assume (as per the problem statement) that x.len() == y.len() == z.len() > 0
    let n = x.len();

    // Check if the coefficient tensor is 1×1×1.
    // We can index directly because the problem guarantees all dimensions are non-empty.
    if c.len() == 1 && c[0].len() == 1 && c[0][0].len() == 1 {
        let only_coeff = c[0][0][0];
        // Fill the output vector with the single coefficient value.
        mk_filled_vec(n, only_coeff)
    } else {
        // In all other cases, fill the output with zeros.
        mk_filled_vec(n, 0.0)
    }
}

